<?php require_once __DIR__.'/../api/bootstrap.php';require_login();$q=trim($_GET['q']??'');$rows=$q?cid_find($q,100):[];$count=(int)db()->query('SELECT COUNT(*) n FROM cids')->fetch()['n'];render_header('CID-10');?><h1>CID-10</h1><div class="card"><p><strong><?=number_format($count,0,',','.')?></strong> códigos na base local.</p><form><label>Pesquisar código ou descrição</label><input name="q" value="<?=e($q)?>" placeholder="Ex.: I10, hipertensão, lombalgia"><br><br><button class="btn">Pesquisar</button> <a class="btn" href="/medical/cid/sync.php">Sincronizar base completa</a></form></div><?php if($q):?><div class="card"><h2>Resultados</h2><?php foreach($rows as $r):?><p><strong><?=e($r['codigo'])?></strong> — <?=e($r['descricao'])?></p><?php endforeach;if(!$rows):?><p class="muted">Nenhum resultado local.</p><?php endif;?></div><?php endif;?><?php render_footer();?>